	private static List<Long> scanContexts(PatternPlan pattern, NativeLmdbQuerySource source) throws IOException {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("subject", 0);
		names.put("context", 1);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN_ID);
		row.recomputeBoundMask();
		List<Long> contexts = new ArrayList<>();
		try (RowCursor cursor = pattern.open(row)) {
			while (cursor.next()) {
				contexts.add(row.slots[1]);
			}
		}
		return contexts;
	}

